using EEMS.Modules.Operations.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;namespace EEMS.Modules.Operations;public static class OperationsModule{public static IServiceCollection AddOperationsModule(this IServiceCollection s,IConfiguration c){var x=c.GetConnectionString("EemsDatabase");if(string.IsNullOrWhiteSpace(x))throw new InvalidOperationException("ConnectionStrings:EemsDatabase is required.");s.AddDbContext<OperationsDbContext>(o=>o.UseNpgsql(x));return s;}}
